From 41b0d49c81faf74cec89bb628ecaf9b6f8da17ef Mon Sep 17 00:00:00 2001
From: Noah <noah@hack.se>
Date: Thu, 2 Jul 2015 02:58:57 +0200
Subject: [PATCH] Keep additional timestamps out of the log text by only
 printing them to the console - also fixes an issue where the logged
 timestamps was the previous time the node was seen (introduced in commit
 d377756f)


diff --git a/wimon.c b/wimon.c
index fdfeb48..2dce9c5 100644
--- a/wimon.c
+++ b/wimon.c
@@ -236,6 +236,12 @@ static const char *nfltoa(const flags_t flags) {
 	return flags_out;
 }

+static const char *timetoa(const time_t *t) {
+	static char s[32];
+	strftime(s, sizeof(s), "%d %b %H:%M:%S", localtime(t));
+	return s;
+}
+
 static void register_db_stmt(sqlite3_stmt **stmt) {
 	prepared_stmts[num_prepared_stmts++] = stmt;
 	assert(num_prepared_stmts <= sizeof(prepared_stmts)/sizeof(prepared_stmts[0]));
@@ -1148,11 +1154,12 @@ static sta_t *lookup_node(const unsigned char *sa, time_t now) {
