+			"after being gone for %ldh%02ldm",
 			mactoa(sta->mac), freq, signal,
 			nfltoa(sta->flags), ssid,
 			sta->flags & NFL_AP? "AP": "Station", mgmttoa(mgmt_st),
-			t / 3600, (t % 3600) / 60, ctime(&tv->tv_sec));
