 	return 0;
@@ -1555,8 +1556,7 @@ static int update(time_t now) {
 			sta->flags & NFL_AP? "AP": "Station",
 			t / 3600, (t % 3600) / 60, ctime(&sta->ping));
 		msg[strlen(msg) - 1] = 0;
-		puts(msg);
-		log_node_message(sta, msg);
+		log_node_message(sta, &now, msg);
