 static void register_db_stmt(sqlite3_stmt **stmt) {
 	prepared_stmts[num_prepared_stmts++] = stmt;
 	assert(num_prepared_stmts <= sizeof(prepared_stmts)/sizeof(prepared_stmts[0]));
 }

